use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut sieve = []
    let mut i = 0
    while i <= limit {
        sieve.push(true)
        i += 1
    }
    let mut counts = []
    let mut largest = []
    let mut c = 0
    let mut last = 0
    let mut k = 0
    while k <= limit {
        if k >= 2 && sieve[k] {
            c += 1
            last = k
            let mut j = k * k
            while j <= limit {
                sieve[j] = false
                j += k
            }
        }
        counts.push(c)
        largest.push(last)
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = s.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

